'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = s => String(s ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = n => Number(n || 0).toLocaleString('en-US');
const money = n => `฿${num(n)}`;
const date = v => new Date(v).toLocaleDateString('en-GB',{timeZone:'Asia/Bangkok',day:'numeric',month:'short'});
const time = v => new Date(v).toLocaleTimeString('en-GB',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit'});
const duration = n => n < 60 ? `${Math.floor(n)} min` : `${Math.floor(n/60)}h ${Math.floor(n%60)}m`;
const paths = {
 grid:'M3 3h6v6H3z M15 3h6v6h-6z M3 15h6v6H3z M15 15h6v6h-6z',
 map:'m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3V6z M9 3v15 M15 6v15',
 car:'m5 7 2-4h10l2 4 M4 7h16l1 10H3L4 7z M6 17v3 M18 17v3 M6 11h2 M16 11h2',
 people:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M16 4a4 4 0 0 1 0 8 M22 21v-3a4 4 0 0 0-3-3 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
 queue:'M9 6h12 M9 12h12 M9 18h12 M3 6h1 M3 12h1 M3 18h1',
 clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',
 chart:'M4 3v18h17 M8 16v-5 M13 16V7 M18 16V4',
 code:'m8 6-6 6 6 6 m8-12 6 6-6 6 M14 3l-4 18',
 flow:'M9 3h6v6H9z M2 16h6v6H2z M16 16h6v6h-6z M12 9v3 M5 16v-4h14v4',
 book:'M4 3h14a2 2 0 0 1 2 2v16H6a2 2 0 0 1-2-2V3z M4 17h16 M8 7h8 M8 11h6',
 settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3l-1 3-3 1-2 3 2 3v3l3 2 3-1 3 1 3-2v-3l2-3-2-3-3-1-1-3H9',
 arrow:'M4 12h16 M14 6l6 6-6 6',
 plus:'M12 5v14 M5 12h14',
 search:'M16 16l5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
 pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
 building:'M5 21V3h14v18 M2 21h20 M9 7h1 M14 7h1 M9 11h1 M14 11h1 M9 15h1 M14 15h1 M10 21v-3h4v3',
 shield:'m12 3 9 4v6c0 5-9 9-9 9s-9-4-9-9V7l9-4z m-4 9 3 3 5-5',
 exit:'M10 3H4v18h6 M8 12h14 M17 7l5 5-5 5',
 enter:'M14 3h6v18h-6 M2 12h14 M11 7l5 5-5 5',
 chevron:'m9 5 7 7-7 7',
 down:'m6 9 6 6 6-6',
 bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',
 check:'m5 12 4 4L19 6',
 close:'M6 6l12 12 M18 6 6 18',
 play:'m8 4 12 8-12 8V4z',
 menu:'M3 6h18 M3 12h18 M3 18h18',
 refresh:'M20 11a8 8 0 0 0-14-5L3 9 M3 3v6h6 M4 13a8 8 0 0 0 14 5l3-3 M15 15h6v6',
 layers:'m12 3 10 5-10 5L2 8l10-5z M2 12l10 5 10-5 M2 16l10 5 10-5',
 spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7z',
 wallet:'M3 7h18v13H3V7z M3 7V4h15v3 M17 12h4v4h-4v-4',
 expand:'M9 3H3v6 M15 3h6v6 M3 15v6h6 M21 15v6h-6',
 camera:'M3 6h4l2-3h6l2 3h4v15H3V6z M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
 info:'M12 11v6 M12 7h.01 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',
 trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const btn = (label,action,ico='arrow',cls='',data='') => `<button type="${action.startsWith('submit-')?'submit':'button'}" class="btn ${cls}" data-action="${action}" ${data}>${icon(ico)}${label}</button>`;
const chip = status => `<span class="chip ${status==='assigned'||status==='waiting'?'amber':status==='disabled'?'red':status==='exited'||status==='cancelled'?'gray':''}">${esc(status)}</span>`;
const empty = (msg,ico='car') => `<div class="empty">${icon(ico)}${esc(msg)}</div>`;
const navItems = {
 overview:['Overview','grid'],parking:['Live parking','map'],driver:['Park my car','car'],find:['Find my car','search'],
 vehicles:['Vehicle registry','people'],queue:['Waiting queue','queue'],history:['Parking history','clock'],analytics:['Analytics','chart'],
 algorithms:['Algorithm lab','code'],architecture:['Architecture','flow'],project:['About the project','book'],presentation:['Presentation','play'],
 settings:['Settings','settings'],security:['Gate operations','shield'],incidents:['Incident log','shield'],simulation:['Simulation control','play']
};
let state, analytics, historyData=[], mergeData, role=localStorage.getItem('parkside-role')||'admin';
let page=location.hash.slice(1)||'overview', floor=0, mapMode='status', days=1, customStart='',customEnd='';
let result=null, found=null, algorithmResult=null, selectedSlot=null, sortOrder='desc', searchQuery='', presentationStep=0;
let animationStep=-1, animationTimer=null, busy=false, lastEventId=0, modalFocus=null,lastRenderAt=0;
const draft={plate:'',destination:'0',findPlate:'',exitPlate:''};
const roles={admin:'Mall administrator',visitor:'Mall visitor',security:'Security staff'};
if(!roles[role]) role='admin';

async function api(path,body,method='POST') {
 const response=await fetch(path,{method:body===undefined?'GET':method,headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});
 const data=await response.json();
 if(!response.ok) throw new Error(typeof data.detail==='string'?data.detail:data.detail?.[0]?.msg||'Something went wrong. Please try again.');
 return data;
}
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className=`show${error?' error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',5500);}
async function refresh(extra=true){
 const [s,a]=await Promise.all([api('/api/state'),extra?api(analyticsUrl()):Promise.resolve(analytics)]);
 state=s;analytics=a;
 if(result?.vehicle){const v=s.vehicles.find(v=>v.plate===result.vehicle.plate);if(v){const changed=v.status!==result.vehicle.status;result.vehicle=v.slot!==result.vehicle.slot?await api(`/api/vehicles/${encodeURIComponent(v.plate)}`):{...result.vehicle,...v};if(changed)toast(`Your parking status: ${v.status}${v.slot?' · '+v.slot:''}`);}else{result=null;}}
 if(found){const v=s.vehicles.find(v=>v.plate===found.plate);found=v?(v.slot!==found.slot?await api(`/api/vehicles/${encodeURIComponent(v.plate)}`):{...found,...v}):null;}
 const last=s.events[0]?.id||0;
 if(lastEventId&&last>lastEventId){const promotion=s.events.find(e=>e.id>lastEventId&&e.kind==='dequeue');if(promotion)toast(promotion.message);}
 lastEventId=last;
}
function analyticsUrl(){return '/api/analytics?days='+days+(customStart&&customEnd?`&start=${encodeURIComponent(customStart)}&end=${encodeURIComponent(customEnd)}`:'');}
async function navigate(target){
 clearInterval(animationTimer);animationTimer=null;animationStep=-1;page=target;location.hash=target;if(page==='analytics')mapMode='heat';
 try{if(page==='history')historyData=(await api(`/api/history?order=${sortOrder}&query=${encodeURIComponent(searchQuery)}`)).records;if(page==='analytics')analytics=await api(analyticsUrl());if(page==='algorithms')mergeData=await api('/api/algorithms/merge');if(page==='simulation'&&!scenarioCatalog.length)scenarioCatalog=(await api('/api/simulation/scenarios')).scenarios;render();window.scrollTo({top:0});}catch(e){toast(e.message,true);}
}
function allowedPages(){return role==='visitor'?['driver','find','parking','queue','project']:role==='security'?['security','parking','find','vehicles','queue','incidents','history','algorithms','simulation','project']:Object.keys(navItems);}
function render(){
 if(!state)return;
 lastRenderAt=Date.now();
 if(!allowedPages().includes(page))page=role==='visitor'?'driver':role==='security'?'security':'overview';
 const mainNav=role==='visitor'?['driver','find','parking','queue']:role==='security'?['security','parking','find','vehicles','queue','incidents','history']:['overview','parking','vehicles','queue','history','analytics'];
 const learnNav=role==='visitor'?['project']:['algorithms','simulation','architecture','project','presentation'].filter(p=>allowedPages().includes(p));
 const nav=items=>items.map(key=>`<button class="${page===key?'active':''}" data-action="nav" data-page="${key}" ${page===key?'aria-current="page"':''}>${icon(navItems[key][1])}${navItems[key][0]}${key==='queue'&&state.waiting_count?`<span class="nav-count">${state.waiting_count}</span>`:''}</button>`).join('');
 $('#app').innerHTML=`<div class="layout"><div class="mobile-shade" data-action="menu-close"></div><aside class="sidebar" aria-label="Main navigation"><div class="brand"><div class="brand-mark">P</div>parkside<span style="color:#91c5a5;margin-left:-10px">.</span></div><div class="mall-label">${icon('building')}<span>${esc(state.settings.mall_name)}</span></div><div class="nav-label">${role==='visitor'?'Your visit':'Workspace'}</div><nav class="nav">${nav(mainNav)}</nav><div class="nav-label">${role==='visitor'?'About':'Explore & learn'}</div><nav class="nav">${nav(learnNav)}${role==='admin'?nav(['settings']):''}</nav><div class="sidebar-foot"><div class="demo-tag"><span class="dot"></span>Interactive prototype</div><p>1,100 bays. 11 floors. One clear view.</p><div class="profile"><div class="avatar">${role==='admin'?'MA':role==='security'?'SC':'MV'}</div><div><strong>${roles[role]}</strong><span>${role==='visitor'?'Welcome to the mall':'Demo workspace'}</span></div></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-button menu-toggle" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><span>Workspace</span>${icon('chevron')}<strong>${navItems[page][0]}</strong></div><div class="top-tools"><span class="sync"><span class="dot"></span>Live · synced ${time(state.updated_at)}</span><select class="role-select" id="role" aria-label="Choose stakeholder view">${Object.entries(roles).map(([k,v])=>`<option value="${k}" ${role===k?'selected':''}>${v}</option>`).join('')}</select><button class="icon-button" data-action="notifications" aria-label="Recent activity">${icon('bell')}</button></div></header><main class="main" id="main" tabindex="-1">${pages[page]() }<footer class="footer"><span>Parkside · 01416206 Data Structures & Algorithms · Group Understaffed</span><span>Illustrative mall layout · Asia/Bangkok</span></footer></main></div></div>`;
 if(busy)$$('button[data-action]').forEach(b=>b.disabled=true);
}
function pageHead(title,subtitle,actions='',eyebrow='Mall parking workspace'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="head-actions">${actions}</div></div>`;}
function stats(){const percent=Math.round(state.occupied/state.capacity*100);return `<div class="stats"><article class="stat"><div class="stat-top"><span>Total parking bays</span>${icon('layers')}</div><div class="number">${num(state.capacity)}</div><div class="stat-note">${state.floors.length} floors <span>·</span> ${state.floors[0].capacity} bays per floor</div></article><article class="stat featured"><div class="stat-top"><span>Available right now</span>${icon('car')}</div><div class="number">${num(state.available)}</div><div class="stat-note"><span class="positive">${icon('check')}</span>Ready for the next arrival</div></article><article class="stat"><div class="stat-top"><span>Occupancy rate</span>${icon('chart')}</div><div class="number">${percent}<span style="font-size:19px">%</span></div><div class="mini-bar"><i style="width:${percent}%"></i></div><div class="stat-note">${num(state.occupied)} occupied / assigned <span>·</span> ${state.disabled} closed</div></article><article class="stat"><div class="stat-top"><span>Vehicles today</span>${icon('enter')}</div><div class="number">${num(state.vehicles_today)}</div><div class="stat-note">${num(state.waiting_count)} waiting <span>·</span> ${money(state.revenue_today)} earned</div></article></div>`;}
function floorOverview(){return `<section class="panel floor-overview"><div class="panel-head"><div><h2>Across the building</h2><p>Occupancy by floor</p></div>${icon('layers')}</div><div class="panel-body">${state.floors.map(f=>`<div class="floor-row ${floor===f.id?'active':''}"><div class="floor-row-top"><button class="text-button" data-action="floor" data-floor="${f.id}" aria-label="View floor ${f.name}"><strong>${f.name} <span>· ${f.zone}</span></strong></button><span>${f.occupied}/${f.capacity}</span></div><div class="floor-track"><i style="width:${f.occupied/f.capacity*100}%"></i></div></div>`).join('')}<div class="capacity-note"><span class="dot"></span>${state.floors.length} connected floors · ${num(state.capacity)} bays</div></div></section>`;}
function mapPanel(title='Live parking map',withAnimation=false){const f=state.floors[floor];return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2><p>Zone ${f.zone} · ${f.available} bays available · select any bay for details</p></div><span class="chip"><span class="dot"></span>Live view</span></div><div class="floor-strip"><span class="label">Floor</span><div class="tabs">${state.floors.map(f=>`<button class="${f.id===floor?'active':''}" data-action="floor" data-floor="${f.id}" aria-label="Floor ${f.name}, ${f.available} available bays" aria-pressed="${f.id===floor}">${f.name}</button>`).join('')}</div></div><div class="map-shell"><div class="map-caption"><span>${esc(state.settings.mall_name)} / ${f.name} parking</span><span>Bidirectional aisles · illustrative distances</span></div>${mapSvg()} </div><div class="map-footer"><div class="legend"><span><i></i>Available</span><span><i class="occupied"></i>Occupied</span><span><i class="assigned"></i>Assigned</span><span><i class="disabled"></i>Closed</span><span><i class="route"></i>Route</span></div><div class="map-mode"><button data-action="map-mode" data-mode="status" class="${mapMode==='status'?'active':''}">Live</button><button data-action="map-mode" data-mode="heat" class="${mapMode==='heat'?'active':''}">Usage heatmap</button></div></div>${withAnimation?`<div class="panel-body">${btn('Show algorithm process','animate-astar','play','secondary')}<div id="astar-metrics">${astarMetrics()}</div></div>`:''}</section>`;}
function mapSvg(){
 const f=state.floors[floor],cols=state.columns,W=1000,H=452;
 const sx=x=>40+x*(920/(cols+1)), sy=y=>({0:45,1:84,2:143,3:184,4:225,5:248,6:271,7:312,8:371,9:412}[y]);
 const selected=page==='find'?found?.route:page==='algorithms'?algorithmResult?.route:result?.vehicle?.route||found?.route||algorithmResult?.route;
 const route=selected?.[role==='visitor'&&page==='find'?'walking':'driving'];
 const chosen=page==='find'?found?.slot:page==='algorithms'?algorithmResult?.algorithm?.slot:result?.vehicle?.slot||found?.slot||algorithmResult?.algorithm?.slot;
 const bw=Math.min(69,920/(cols+1)-7),bh=48;
 const slots=f.slots.map(s=>{
  const x=sx(s.node[1]),y=sy(s.node[2]),recommend=s.id===chosen,heat=analytics?.usage[s.id]||0;
  const fill=recommend?'#e8f1d7':mapMode==='heat'?`hsl(135 27% ${96-Math.min(8,heat)*6}%)`:s.status==='available'?'#e4f3e6':s.status==='assigned'?'#ffedc8':s.status==='disabled'?'#f9e4de':'#e4e9e1';
  const stroke=recommend?'#508454':s.status==='available'?'#aacbb1':s.status==='assigned'?'#d3b579':s.status==='disabled'?'#d9b2a6':'#d5dcd2';
  const text=s.status==='available'||recommend?'#4e7957':'#8b9587';
  return `<g class="map-slot" data-action="slot" data-slot="${s.id}" role="button" tabindex="0" aria-label="Bay ${s.id}, ${s.status}${s.plate?', '+esc(s.plate):''}"><rect x="${x-bw/2}" y="${y-bh/2}" width="${bw}" height="${bh}" rx="5" fill="${fill}" stroke="${stroke}" stroke-width="${recommend?2:1}"/>${s.plate?`<g class="car" transform="translate(${x-6},${y-16})" fill="none" stroke="${s.status==='assigned'?'#bb8c3e':'#9aab96'}" stroke-width="1.2"><rect width="12" height="24" rx="4"/><path d="M2 6h8 M2 17h8 M1 8h10 M1 15h10"/></g>`:s.status==='disabled'?`<path d="m${x-5} ${y-13} 10 10 m-10 0 10-10" stroke="#c28c7b"/>`:recommend?`<circle cx="${x}" cy="${y-9}" r="5" fill="#639158"/>`:''}<text class="bay-number" x="${x}" y="${y+17}" text-anchor="middle" fill="${text}">${String(s.index+1).padStart(2,'0')}</text></g>`;
 }).join('');
 const routePath=page==='find'&&role==='visitor'?[...(route?.path||[])].reverse():route?.path||[];
 const path=routePath.filter(n=>n[0]===floor)||[];
 const pathData=path.map((n,i)=>`${i?'L':'M'}${sx(n[1])},${sy(n[2])}`).join(' ');
 const steps=route?.steps||[],step=steps[animationStep];
 const explored=animationStep>=0?steps.slice(0,animationStep+1).filter(s=>s.node[0]===floor).map(s=>`<circle cx="${sx(s.node[1])}" cy="${sy(s.node[2])}" r="3" fill="#69ad9b" opacity=".4"/>`).join(''):'';
 const dest=state.destinations.find(d=>d.floor===floor),destX=dest?sx(dest.node[1]):sx(cols+1);
 const arrows=[0,3,6,9].map(y=>`<path d="M${sx(9)} ${sy(y)}h${y%2?-32:32}" stroke="#bcc8b6" stroke-width="1.3" marker-end="url(#lane-arrow)"/>`).join('');
 return `<svg viewBox="0 0 ${W} ${H}" aria-label="Interactive parking map for floor ${f.name}" role="group"><defs><marker id="lane-arrow" markerWidth="6" markerHeight="6" refX="4" refY="3" orient="auto"><path d="M0 0l5 3-5 3" fill="none" stroke="#b2c1af"/></marker><marker id="route-arrow" markerWidth="5" markerHeight="5" refX="4" refY="2.5" orient="auto"><path d="M0 0l5 2.5L0 5" fill="#36816b"/></marker></defs><rect x="12" y="24" width="976" height="411" rx="18" fill="#f2f6ed" stroke="#e2e9dd"/><path d="M40 45h920v367H40V45 M40 184h920 M40 225h920 M40 271h920" fill="none" stroke="#fff" stroke-width="21"/><path d="M40 45h920 M40 184h920 M40 271h920 M40 412h920" stroke="#e0e8d8" stroke-dasharray="4 7" fill="none"/>${arrows}${slots}<text x="17" y="15" fill="#85967e" font-size="10" letter-spacing="1">ZONE ${f.zone} · ${f.name}</text><rect x="9" y="211" width="78" height="28" rx="6" fill="#e1e9da"/><text x="48" y="229" text-anchor="middle" fill="#64805a" font-size="9">${floor===0?'ENTRY / EXIT':'FLOOR RAMP'}</text><rect x="904" y="210" width="78" height="30" rx="6" fill="#e4ecd9"/><text x="943" y="229" text-anchor="middle" fill="#658056" font-size="10">↑ LIFT / STAIRS</text>${dest?`<circle cx="${destX}" cy="225" r="5" fill="#709363"/><text x="${Math.max(125,Math.min(840,destX))}" y="249" text-anchor="middle" fill="#6c855d" font-size="9">${esc(dest.name)}</text>`:''}${explored}${path.length&&animationStep<0?`<path d="${pathData}" fill="none" stroke="#3d896f" stroke-width="3" stroke-linejoin="round" stroke-linecap="round" marker-end="url(#route-arrow)"/><circle cx="${sx(path[0][1])}" cy="${sy(path[0][2])}" r="4" fill="#3d896f"/>`:''}${step?.node[0]===floor?`<circle cx="${sx(step.node[1])}" cy="${sy(step.node[2])}" r="6" fill="#2e806b"/>`:''}<text x="20" y="448" fill="#8e9c84" font-size="8">${path.length?`${role==='visitor'&&page==='find'?'Walking':'Driving'} route · ${route.distance} m total${route.path.some(n=>n[0]!==floor)?' · use the floor ramp to continue':''}`:'Select a bay to see its status and vehicle details.'}</text><text x="978" y="448" text-anchor="end" fill="#8e9c84" font-size="8">N ↑</text></svg>`;
}
function occupancyChart(){
 const values=analytics.hours.filter(h=>h.occupancy!==null),max=Math.max(10,...values.map(h=>h.occupancy)),W=520,H=155;
 const x=h=>42+h/23*460,y=n=>120-n/max*95;
 const pts=values.map(h=>`${x(h.hour)},${y(h.occupancy)}`),line=pts.map((p,i)=>(i?'L':'M')+p).join(' ');
 return `<div class="chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Hourly occupancy from recorded sessions, ${values.map(h=>`${h.hour}:00 ${h.occupancy}`).join('; ')}"><defs><linearGradient id="chart-fade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#75b69c" stop-opacity=".25"/><stop offset="1" stop-color="#75b69c" stop-opacity="0"/></linearGradient></defs>${[0,.5,1].map(p=>`<line x1="42" x2="504" y1="${y(max*p)}" y2="${y(max*p)}" stroke="#e9eee5" stroke-dasharray="3 4"/><text x="30" y="${y(max*p)+3}" text-anchor="end" fill="#97a18f" font-size="9">${Math.round(max*p)}</text>`).join('')}${values.length?`<path d="${line} L${x(values.at(-1).hour)},120 L${x(values[0].hour)},120 Z" fill="url(#chart-fade)"/><path d="${line}" fill="none" stroke="#37886e" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>${values.map(h=>`<circle cx="${x(h.hour)}" cy="${y(h.occupancy)}" r="2" fill="#37886e"><title>${h.hour}:00 · ${h.occupancy} occupied bays</title></circle>`).join('')}`:''}${[0,4,8,12,16,20,23].map(h=>`<text x="${x(h)}" y="143" text-anchor="middle" fill="#99a492" font-size="9">${String(h).padStart(2,'0')}:00</text>`).join('')}</svg></div>`;
}
function flowChart(){const hours=analytics.hours,max=Math.max(1,...hours.map(h=>Math.max(h.entries,h.exits)));return `<div class="chart"><svg viewBox="0 0 520 155" role="img" aria-label="Entries and exits by Bangkok hour"><line x1="30" x2="510" y1="120" y2="120" stroke="#e5ecdd"/>${hours.map(h=>`<rect x="${32+h.hour*19.5}" y="${120-h.entries/max*95}" width="6" height="${h.entries/max*95}" rx="2" fill="#3d8b71"><title>${h.hour}:00 · ${h.entries} entries</title></rect><rect x="${40+h.hour*19.5}" y="${120-h.exits/max*95}" width="6" height="${h.exits/max*95}" rx="2" fill="#bed6bc"><title>${h.hour}:00 · ${h.exits} exits</title></rect>`).join('')}${[0,4,8,12,16,20].map(h=>`<text x="${38+h*19.5}" y="143" text-anchor="middle" fill="#99a492" font-size="9">${String(h).padStart(2,'0')}:00</text>`).join('')}</svg></div>`;}
function recentActivity(limit=4){return state.events.length?state.events.slice(0,limit).map(e=>`<div class="activity-row"><div class="activity-symbol">${icon(e.kind==='exit'?'exit':e.kind==='enqueue'?'queue':e.kind==='incident'?'shield':'enter')}</div><div class="activity-text"><strong>${esc(e.message)}</strong><span>${esc(e.kind)} · ${date(e.time)}</span></div><time>${time(e.time)}</time></div>`).join(''):empty('Activity will appear when vehicles arrive.','clock');}
function chartPanel(title,subtitle,chart){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2><p>${subtitle}</p></div><span class="chip gray">${days===1?'Today':days+' days'}</span></div><div class="panel-body">${chart}</div></section>`;}
function overviewPage(){return pageHead('Your parking, at a glance.','A clear view of every arrival, bay and departure.',btn('Simulation tools','simulation','play','secondary')+btn('Register arrival','arrival','plus'))+stats()+`<div class="content-grid">${mapPanel()}<div class="side-stack">${floorOverview()}<div class="callout">${icon('spark')}<div class="eyebrow">Smarter arrivals</div><h3>The right bay.<br>A shorter walk.</h3><p>A* finds a connected route to an available bay near your visitor’s destination.</p>${btn('Explore the algorithm','nav','arrow','secondary small','data-page="algorithms"')}</div></div></div><div class="bottom-grid">${chartPanel('Parking throughout the day','Occupied / assigned bays · recorded hourly',occupancyChart())}<section class="panel"><div class="panel-head"><div><h2>Recent activity</h2><p>Every movement, in one place</p></div><button class="text-button" data-action="nav" data-page="history">View history ${icon('arrow')}</button></div><div class="panel-body">${recentActivity()}</div></section></div><div class="small-stats"><div class="small-stat"><span>Revenue today</span><strong>${money(state.revenue_today)}</strong><p>Completed visits · configured demo fees</p></div><div class="small-stat"><span>Average completed stay</span><strong>${duration(state.average_duration)}</strong><p>Visits that exited today</p></div><div class="small-stat"><span>Average bay turnover</span><strong>${state.turnover_today}</strong><p>Completed visits today / total bays</p></div></div>`;}
function parkingPage(){return pageHead('A space for every visit.','All 1,100 bays, with connected routes between 11 floors.',role==='visitor'?btn('Find a bay','nav','car','','data-page="driver"'):btn('Register arrival','arrival','plus'))+`<div class="content-grid">${mapPanel('Live parking map',!!(result?.vehicle?.route||found?.route||algorithmResult?.route))}<div class="side-stack">${floorOverview()}<div class="callout"><div class="eyebrow">${result?.vehicle?'Your assigned bay':'Floor '+state.floors[floor].name}</div><h3>${result?.vehicle?.slot||`${state.floors[floor].available} bays available`}</h3><p>${result?.vehicle?esc(result.vehicle.plate)+' · '+esc(result.vehicle.destination_name):'Choose a destination to find your closest connected bay.'}</p>${btn('Park my car','nav','arrow','secondary small','data-page="driver"')}</div></div></div>${(result?.vehicle||found)?.route?`<div class="notice" style="margin-top:20px">${icon('info')}The route may cross floors. Select each floor tab to follow its segment. Distance includes illustrative floor-ramp costs.</div>`:''}`;}
function destinationsOptions(value=draft.destination){return state.destinations.map(d=>`<option value="${d.id}" ${String(d.id)===String(value)?'selected':''}>${esc(d.name)} · ${state.floors[d.floor].name}</option>`).join('');}
function entryForm(){return `<form class="form" data-form="entry"><label class="field">License plate<input name="plate" data-draft="plate" value="${esc(draft.plate)}" placeholder="e.g. กข 1234 or ABC-1234" required minlength="2" maxlength="40" autocomplete="off"><small>Thai and international plates supported</small></label><label class="field">Where are you heading?<select name="destination" data-draft="destination">${destinationsOptions()}</select></label>${btn('Find my parking bay','submit-entry','arrow','wide')}<button type="button" class="text-button" data-action="camera">${icon('camera')} Simulate camera detection</button></form>`;}
function vehicleResult(v,algorithm=null){if(!v)return '';return `<div class="result-card"><span class="chip ${v.status==='waiting'?'amber':''}">${v.status==='waiting'?'In the waiting queue':v.status==='assigned'?'Bay reserved for your arrival':'Your car is parked'}</span><h3>${esc(v.plate)} ${icon('arrow')} ${v.slot||'Position #'+v.queue_position}</h3><p class="muted" style="font-size:10px">${esc(v.destination_name)}${v.floor!==null?' · Floor '+state.floors[v.floor].name+' / Zone '+state.floors[v.floor].zone:''}</p><div class="result-grid"><div><span>${v.status==='waiting'?'Waiting time':'Parking duration'}</span><strong>${duration(v.duration_minutes)}</strong></div><div><span>${v.route?'Walking distance':'Queue position'}</span><strong>${v.route?v.route.walking.distance+' m':'#'+v.queue_position}</strong></div><div><span>Estimated fee</span><strong>${money(v.estimated_fee)}</strong></div></div><div class="result-actions">${v.route?btn('View route','route','map','secondary small',`data-plate="${esc(v.plate)}"`):btn('Leave queue','cancel','close','danger small',`data-plate="${esc(v.plate)}"`)}${v.status==='assigned'?btn('Confirm parking','confirm','check','small',`data-plate="${esc(v.plate)}"`):''}</div>${algorithm?`<p class="muted" style="font-size:9px;margin-top:13px">A* · ${algorithm.evaluated} candidates evaluated · ${num(algorithm.nodes_explored)} nodes explored · ${algorithm.execution_ms} ms</p>`:''}${v.status==='waiting'?'<p class="muted" style="font-size:10px;margin-top:13px">Your status updates here when a bay opens. The oldest waiting visitor is served first.</p>':''}</div>`;}
function driverPage(){return `<div class="hero"><div><div class="eyebrow">Welcome to ${esc(state.settings.mall_name)}</div><h1>Less circling.<br>More shopping.</h1><p>Tell us where you’re heading. We’ll find an available bay nearby and guide you there.</p><div class="result-actions">${btn('Park my car','scroll-park','arrow','mint')}${btn('Find my car','nav','search','secondary','data-page="find"')}</div></div><div class="hero-visual"><svg viewBox="0 0 240 180" aria-hidden="true"><path d="M18 140h200M40 30v110M198 30v110" stroke="#48796b" fill="none" stroke-dasharray="5 7"/><rect x="65" y="28" width="108" height="140" rx="22" fill="#315c4e"/><rect x="82" y="47" width="74" height="104" rx="16" fill="#b5dcb8"/><path d="M87 73h64M87 123h64M90 55h58l-4 14H94zM94 128h51l4 14H90z" fill="none" stroke="#547d58" stroke-width="3"/><circle cx="179" cy="39" r="22" fill="#dcf0bb"/><path d="m170 38 6 6 11-13" fill="none" stroke="#41764d" stroke-width="3"/></svg></div></div><div class="forms-grid"><section class="panel" id="park-form"><div class="panel-head"><h2><span class="step-label">01</span>Plan your arrival</h2><span class="chip">${state.available} bays free</span></div><div class="panel-body">${entryForm()}${vehicleResult(result?.vehicle,result?.algorithm)}</div></section><section class="panel"><div class="panel-head"><h2><span class="step-label">02</span>A smoother visit</h2></div><div class="panel-body"><div class="activity-row"><div class="activity-symbol">${icon('pin')}</div><div class="activity-text"><strong>Park near your destination</strong><span>Shortest connected walking distance to your destination</span></div></div><div class="activity-row"><div class="activity-symbol">${icon('layers')}</div><div class="activity-text"><strong>11 floors, connected</strong><span>100 bays on each floor · follow the ramp when required</span></div></div><div class="activity-row"><div class="activity-symbol">${icon('wallet')}</div><div class="activity-text"><strong>${state.settings.free_hours} hours free</strong><span>Then ${money(state.settings.first_hour)} for the first billed hour, ${money(state.settings.additional_hour)} per additional hour</span></div></div><div class="activity-row"><div class="activity-symbol">${icon('queue')}</div><div class="activity-text"><strong>A fair waiting queue</strong><span>If parking is full, your position updates automatically</span></div></div><div class="notice" style="margin-top:20px;margin-bottom:0">Fees and layouts are demonstration settings. Check the mall’s actual policy before your visit.</div></div></section></div>${mapPanel('Your parking route')}`;}
function findPage(){return pageHead('Find your way back.','Enter your plate to locate your car and see a walking route.','','Your mall visit')+`<section class="panel" style="margin-bottom:20px"><div class="panel-head"><h2>Your car, a quick search away</h2><span class="chip">Plate lookup</span></div><div class="panel-body"><form class="form-inline" data-form="find"><label class="field">License plate<input name="plate" data-draft="findPlate" value="${esc(draft.findPlate)}" placeholder="e.g. กข 1234" required minlength="2" maxlength="40"></label>${btn('Find my car','submit-find','search')}</form>${vehicleResult(found)}</div></section>${mapPanel('Walking route to your car')}<div class="notice" style="margin-top:20px">${icon('info')}The map draws the connected route between your selected destination and bay. Distances and shared aisle paths are illustrative.</div>`;}
function vehiclesPage(){const records=state.vehicles.filter(v=>v.plate.toLowerCase().includes(searchQuery.toLowerCase().replace(/[\s-]/g,'')));return pageHead('Every vehicle, accounted for.','Plate-keyed records for parked, assigned and waiting vehicles.',btn('Register arrival','arrival','plus'))+`<section class="panel"><div class="panel-head"><h2>Active vehicle registry</h2><span class="chip">Hash table · average O(1)</span></div><div class="toolbar"><input class="search-input" id="vehicle-search" placeholder="Search license plate…" value="${esc(searchQuery)}" aria-label="Filter active vehicles"><span class="muted" style="font-size:10px">${records.length} active records · ${state.occupied} in bays</span></div>${records.length?`<div class="table-wrap"><table><thead><tr><th>License plate</th><th>Bay / Floor</th><th>Destination</th><th>Entry</th><th>Duration</th><th>Status</th><th>Action</th></tr></thead><tbody>${records.slice(0,150).map(v=>`<tr><td><strong>${esc(v.plate)}</strong>${v.is_demo?'<br><small class="muted">Demo</small>':''}</td><td>${v.slot||'Queue #'+v.queue_position}${v.floor!==null?' / '+state.floors[v.floor].name:''}</td><td>${esc(v.destination_name)}</td><td>${time(v.entry_time)}</td><td>${duration(v.duration_minutes)}</td><td>${chip(v.status)}</td><td>${btn('Locate','route','pin','secondary small',`data-plate="${esc(v.plate)}"`)} ${v.status==='waiting'?btn('Cancel','cancel','close','danger small',`data-plate="${esc(v.plate)}"`):btn('Exit','exit','exit','secondary small',`data-plate="${esc(v.plate)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('No vehicles match this plate.')}<div class="panel-body" style="padding-top:15px"><small class="muted">${records.length>150?'Showing 150 matches. Use plate search to narrow the list.':'All matching active records shown.'}</small></div></section>`;}
function queuePage(){return pageHead('A fair place in line.','First in, first out. A released bay goes to the oldest waiting vehicle.',role!=='visitor'?btn('Create a demo queue','simulate','queue','secondary','data-sim="queue"'):'')+`<div class="notice">${icon('queue')} ${state.waiting_count?`${state.waiting_count} vehicles waiting. Queue positions update when vehicles cancel or a bay opens.`:'No waiting vehicles right now. Visitors join automatically when all reachable open bays are taken.'}</div><section class="panel"><div class="panel-head"><h2>FIFO waiting queue</h2><span class="chip">Enqueue / dequeue · O(1)</span></div><div class="panel-body"><div class="eyebrow" style="margin-bottom:12px">Front → rear</div>${state.queue.length?`<div class="queue-line">${state.queue.map((v,i)=>`<article class="queue-card"><span class="queue-no">${i===0?'FRONT · NEXT IN':'POSITION #'+(i+1)}</span><h3>${esc(v.plate)}</h3><p>${esc(v.destination_name)}<br>Waiting ${duration(v.duration_minutes)}</p>${btn('Cancel queue entry','cancel','close','secondary small',`data-plate="${esc(v.plate)}"`)}</article>${i<state.queue.length-1?`<div class="queue-arrow">${icon('arrow')}</div>`:''}`).join('')}</div>`:empty('The queue is empty.','queue')}<div class="codebox">enqueue(plate) → rear<br>front() → ${esc(state.queue[0]?.plate||'empty')}<br>dequeue() → when a reachable bay is released<br>is_empty() → ${state.queue.length===0}<br>Cancellation scans the queue: O(n). Fee timing starts when a bay is assigned.</div></div></section>${role!=='visitor'?`<section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Queue event stream</h2></div><div class="panel-body">${state.events.filter(e=>['enqueue','dequeue','cancel'].includes(e.kind)).slice(0,8).map(e=>`<div class="activity-row"><div class="activity-symbol">${icon(e.kind==='dequeue'?'enter':'queue')}</div><div class="activity-text"><strong>${esc(e.message)}</strong><span>${esc(e.kind)} · ${time(e.time)}</span></div></div>`).join('')||empty('Enqueue and dequeue operations appear here.','queue')}</div></section>`:''}`;}
function historyPage(){return pageHead('The story of every visit.','Completed visits and cancelled queue entries, ordered with explicit Merge Sort.')+`<section class="panel"><div class="panel-head"><h2>Parking history</h2><span class="chip">Merge Sort · O(n log n)</span></div><div class="toolbar"><form data-form="history" class="form-inline" style="flex:1"><input class="search-input" name="query" placeholder="Search history by plate…" aria-label="History plate filter" value="${esc(searchQuery)}">${btn('Search','submit-history','search','secondary small')}</form><select class="role-select" id="history-order" aria-label="Sort history"><option value="desc" ${sortOrder==='desc'?'selected':''}>Newest entry first</option><option value="asc" ${sortOrder==='asc'?'selected':''}>Oldest entry first</option></select>${btn('Visualize Merge Sort','nav','code','secondary small','data-page="algorithms"')}</div>${historyData.length?`<div class="table-wrap"><table><thead><tr><th>Vehicle</th><th>Bay / Floor</th><th>Entry</th><th>Exit</th><th>Duration</th><th>Fee</th><th>Status</th></tr></thead><tbody>${historyData.slice(0,150).map(v=>`<tr><td><strong>${esc(v.plate)}</strong>${v.is_demo?'<br><small class="muted">Demo</small>':''}</td><td>${v.slot||'—'}${v.floor!==null?' / '+state.floors[v.floor].name:''}</td><td>${date(v.entry_time)} · ${time(v.entry_time)}</td><td>${date(v.exit_time)} · ${time(v.exit_time)}</td><td>${duration(v.duration_minutes)}</td><td>${money(v.fee)}</td><td>${chip(v.status)}</td></tr>`).join('')}</tbody></table></div>`:empty('No completed visits match your search.','clock')}<div class="panel-body" style="padding-top:15px"><small class="muted">${num(historyData.length)} matching records · showing up to 150 · all fees stored at exit</small></div></section>`;}
function analyticsPage(){
 const peak=analytics.peak,top=analytics.top_slots[0],rangeLabel=customStart?`${date(customStart)} – ${date(customEnd)}`:days===1?'Today':`Last ${days} days`;
 return pageHead('Make room for better decisions.','Recorded visits become useful signals for mall operations.',`<div class="tabs">${[1,7,30].map(n=>`<button data-action="range" data-days="${n}" class="${days===n&&!customStart?'active':''}">${n===1?'Today':n+' days'}</button>`).join('')}<button data-action="custom-range">Custom range</button></div>`)+`<div class="notice">${icon('info')} ${esc(rangeLabel)} · ${num(analytics.entries)} arrivals, ${num(analytics.assignments)} assignments, ${num(analytics.exits)} exits. ${top?`Bay ${top.slot} led demand with ${top.uses} assignments.`:'No assignments recorded in this range.'} ${peak?`Peak hourly occupancy: ${peak.hour}:00, ${Math.round(peak.occupancy/state.capacity*100)}% (${peak.occupancy} bays).`:''}</div><div class="stats"><div class="stat"><div class="stat-top"><span>Peak hourly occupancy</span>${icon('chart')}</div><div class="number">${peak?Math.round(peak.occupancy/state.capacity*100):0}%</div><div class="stat-note">${peak?String(peak.hour).padStart(2,'0')+':00':'No samples'} · average of hourly samples</div></div><div class="stat featured"><div class="stat-top"><span>Completed revenue</span>${icon('wallet')}</div><div class="number">${money(analytics.revenue)}</div><div class="stat-note">Stored fee totals from exits in range</div></div><div class="stat"><div class="stat-top"><span>Average occupancy</span>${icon('car')}</div><div class="number">${Math.round(analytics.average_occupancy/state.capacity*100)}%</div><div class="stat-note">${analytics.average_occupancy} bays across measured hours</div></div><div class="stat"><div class="stat-top"><span>Arrival rate</span>${icon('enter')}</div><div class="number">${analytics.arrival_rate}<span style="font-size:15px"> /h</span></div><div class="stat-note">All arrivals / elapsed range hours</div></div></div><div class="bottom-grid" style="margin-top:0">${chartPanel('Occupancy over time','Average occupied bays at each Bangkok hour',occupancyChart())}${chartPanel('Entries vs exits','Hour of entry / exit · selected date range','<div class="chart-legend"><span><i></i>Entries</span><span><i class="light"></i>Exits</span></div>'+flowChart())}</div><div class="bottom-grid"><section class="panel"><div class="panel-head"><h2>Most used bays</h2><span class="chip gray">${esc(rangeLabel)}</span></div>${analytics.top_slots.length?`<div class="table-wrap"><table><thead><tr><th>Bay</th><th>Assignments</th><th>Uses / day</th><th>Avg completed stay</th></tr></thead><tbody>${analytics.top_slots.map(s=>`<tr><td><button class="text-button" data-action="slot" data-slot="${s.slot}">${s.slot}</button></td><td>${s.uses}</td><td>${(s.uses/Math.max(1,Math.ceil((new Date(analytics.range_end)-new Date(analytics.range_start))/86400000))).toFixed(2)}</td><td>${s.average_minutes?duration(s.average_minutes):'No completed visits'}</td></tr>`).join('')}</tbody></table></div>`:empty('No assignments for this date range.','chart')}</section><section class="panel"><div class="panel-head"><h2>Parking duration</h2><p>Completed visits in range</p></div><div class="panel-body">${['Under 1 hour','1–2 hours','2–4 hours','4+ hours'].map((label,i)=>`<div class="floor-row"><div class="floor-row-top"><strong>${label}</strong><span>${analytics.distribution[i]} visits</span></div><div class="floor-track"><i style="width:${analytics.distribution[i]/Math.max(1,analytics.exits)*100}%"></i></div></div>`).join('')}<p class="heat-note">${analytics.exits?`${analytics.distribution[2]} completed visits lasted 2–4 hours.`:'Completed visits will populate this distribution.'}</p></div></section></div><div class="content-grid" style="margin-top:20px">${mapPanel('Assignment heatmap')}<div class="side-stack">${floorOverview()}<div class="callout"><div class="eyebrow">From data to action</div><h3>${top?top.slot+' is the most used bay.':'Start collecting visits.'}</h3><p>${top?`${top.uses} assignments in this range. Use the heatmap to compare demand, and review destinations before adjusting signage.`:'Run a simulation to see how arrivals and exits shape your parking data.'}</p></div></div></div><p class="heat-note">Heatmap shows assignments from the selected range. Proximity alone does not establish why a bay is popular. Closed bays reduce availability; occupancy percentages use physical capacity.</p>`;
}
function astarMetrics(){const route=algorithmResult?.route||result?.vehicle?.route||found?.route,algo=algorithmResult?.algorithm||result?.algorithm,step=route?.driving.steps?.[animationStep];return `<div class="metrics-strip"><span>Recommended bay<strong>${algo?.slot||result?.vehicle?.slot||found?.slot||'Run A*'}</strong></span><span>Drive / walk<strong>${route?route.driving.distance+'m / '+route.walking.distance+'m':'—'}</strong></span><span>Expanded nodes<strong>${route?route.driving.expanded:'—'}</strong></span><span>Execution<strong>${algo?.execution_ms??'—'} ms</strong></span></div>${step?`<div class="codebox">Node: (${step.node.join(', ')})<br>g(n) = ${step.g} · h(n) = ${step.h} · f(n) = ${step.f}<br>Open heap entries: ${step.open} · closed / expanded: ${step.closed}<br>Open nodes (first 8): ${step.open_nodes.slice(0,8).map(n=>'('+n.join(',')+')').join(' ')}<br>Operation: expand current node and relax its neighbors</div><div class="progress"><i style="width:${(animationStep+1)/route.driving.steps.length*100}%"></i></div>`:''}`;}
function algorithmsPage(){return pageHead('The algorithms behind the arrival.','Inspect the real operations used by the parking service.',btn('Guided presentation','nav','play','secondary','data-page="presentation"'))+benchmarkPanel()+`<div class="algorithm-grid"><section class="panel algorithm-card"><div class="panel-head"><div class="algorithm-title"><div class="algo-mark">#</div><h2>Hash table</h2></div><span class="chip">Vehicle registry</span></div><div class="panel-body"><p>Normalized license plates are dictionary keys. Insert and find a vehicle without scanning all parked cars; status updates and exits use the same registry.</p><div class="complexity"><span class="chip gray">Average lookup O(1)</span><span class="chip gray">Worst case O(n) · space O(n)</span></div><div class="codebox">${state.vehicles.slice(0,6).map(v=>`${esc(v.plate)} → ${v.slot||'waiting #'+v.queue_position} (${v.status})`).join('<br>')||'Registry empty'}</div><div class="result-actions">${btn('Insert','arrival','plus','secondary small')}${btn('Search','nav','search','secondary small','data-page="find"')}${btn('Update / remove','nav','people','secondary small','data-page="vehicles"')}</div><p style="margin:12px 0 0;font-size:10px">Update: confirm an assigned vehicle. Remove: record its exit or cancel its queue entry.</p></div></section><section class="panel algorithm-card"><div class="panel-head"><div class="algorithm-title"><div class="algo-mark">↔</div><h2>FIFO queue</h2></div><span class="chip">Fair waiting</span></div><div class="panel-body"><p>When reachable parking is full, enqueue at the rear. A released bay is assigned to the front vehicle, and an in-app notification records the dequeue.</p><div class="complexity"><span class="chip gray">Enqueue / dequeue O(1)</span><span class="chip gray">Space O(n)</span></div><div class="codebox">FRONT → ${state.queue.slice(0,4).map(v=>esc(v.plate)).join(' → ')||'empty'} → REAR<br>front(): ${esc(state.queue[0]?.plate||'null')}<br>is_empty(): ${state.waiting_count===0}</div><div class="result-actions">${btn('Enqueue demo vehicles','simulate','plus','secondary small','data-sim="queue"')}${btn('Release bay / dequeue','simulate','exit','secondary small','data-sim="exit"')}</div></div></section><section class="panel algorithm-card"><div class="panel-head"><div class="algorithm-title"><div class="algo-mark">A*</div><h2>A* routing</h2></div><span class="chip">Connected paths</span></div><div class="panel-body"><p>Search valid aisle and ramp edges. Rank available bays by actual walking distance, then driving distance. Each search uses f(n) = g(n) + h(n).</p><div class="complexity"><span class="chip gray">Heap search O((V + E) log V)</span><span class="chip gray">Space O(V + E)</span></div><label class="field">Destination<select id="lab-destination">${destinationsOptions()}</select></label><div class="result-actions" style="margin-top:14px">${btn('Run recommendation','run-astar','play','secondary small')}${btn('Animate search','animate-astar','play','small')}</div><div id="astar-metrics">${astarMetrics()}</div></div></section><section class="panel algorithm-card"><div class="panel-head"><div class="algorithm-title"><div class="algo-mark">⇅</div><h2>Merge Sort</h2></div><span class="chip">Visit history</span></div><div class="panel-body"><p>Divide history into smaller lists, then merge them by entry timestamp. The sorting function used by history also produces this eight-record trace.</p><div class="complexity"><span class="chip gray">Time O(n log n)</span><span class="chip gray">Space O(n)</span></div><div id="merge-trace"><div class="trace-label">Input · entry times</div><div class="trace">${mergeData?.input.map(v=>`<span>${time(v)}</span>`).join('')||'No completed visits yet'}</div></div>${btn('Animate Merge Sort','animate-merge','play','secondary small')}<p style="font-size:10px;margin:12px 0 0">The UI displays times; the algorithm compares full timestamps, including dates.</p></div></section></div><div style="margin-top:20px">${mapPanel('A* search visualization',true)}</div><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Why these algorithms?</h2>${btn('Compare A* vs Dijkstra','compare','chart','secondary small')}</div><div id="compare-output" class="panel-body" style="display:none"></div><div class="table-wrap"><table><thead><tr><th>Task</th><th>Selected method</th><th>Alternative</th><th>Reason</th></tr></thead><tbody><tr><td>Plate lookup</td><td>Hash table · avg O(1)</td><td>Linear search · O(n)</td><td>Direct key access as the registry grows</td></tr><tr><td>Routing</td><td>A* · weighted graph</td><td>BFS / Dijkstra</td><td>BFS ignores unequal ramp costs; A* adds a safe heuristic to Dijkstra</td></tr><tr><td>Waiting</td><td>FIFO queue · O(1)</td><td>Priority queue</td><td>Serve the earliest visitor fairly</td></tr><tr><td>History order</td><td>Stable Merge Sort · O(n log n)</td><td>Insertion Sort · O(n²)</td><td>Predictable performance and stable equal-entry ordering</td></tr></tbody></table></div><div class="panel-body" style="padding-top:15px"><small class="muted">A* complexity describes one search in this consistent-heuristic graph; recommendation can run searches for several candidates. UI traces, JSON serialization and database reads add separate overhead.</small></div></section>`;}
function securityPage(){return pageHead('Keep every arrival moving.','Register vehicles, verify assigned bays, and record departures.','','Security operations')+`<div class="forms-grid"><section class="panel"><div class="panel-head"><h2>${icon('enter')} Register vehicle entry</h2><span class="chip">Manual / simulated</span></div><div class="panel-body">${entryForm()}${vehicleResult(result?.vehicle,result?.algorithm)}</div></section><section class="panel"><div class="panel-head"><h2>${icon('exit')} Record vehicle exit</h2></div><div class="panel-body"><form class="form" data-form="exit"><label class="field">License plate<input name="plate" data-draft="exitPlate" value="${esc(draft.exitPlate)}" placeholder="Plate at the exit gate" minlength="2" maxlength="40" required></label>${btn('Record exit & calculate fee','submit-exit','exit','wide')}<p class="muted" style="font-size:10px">The visit closes, a fee receipt is created, and the oldest waiting vehicle receives the released bay.</p></form><div class="divider"></div><h3 style="margin-bottom:14px">Assigned vehicles to verify</h3>${state.vehicles.filter(v=>v.status==='assigned').slice(0,5).map(v=>`<div class="activity-row"><div class="activity-text"><strong>${esc(v.plate)} → ${v.slot}</strong><span>Awaiting parking confirmation</span></div>${btn('Confirm','confirm','check','secondary small',`data-plate="${esc(v.plate)}"`)}</div>`).join('')||'<p class="muted" style="font-size:11px">No vehicles awaiting confirmation.</p>'}<div class="result-actions" style="margin-top:20px">${btn('Find a vehicle','nav','search','secondary small','data-page="find"')}${btn('Log an incident','nav','shield','secondary small','data-page="incidents"')}</div></div></section></div>${mapPanel('Security floor monitor')}`;}
function incidentsPage(){return pageHead('A safer parking experience.','Log assistance requests and bay issues, then track their resolution.')+`<div class="forms-grid"><section class="panel"><div class="panel-head"><h2>New security report</h2></div><div class="panel-body"><form class="form" data-form="incident"><label class="field">Bay ID (optional)<input name="slot" placeholder="e.g. A-17" maxlength="12"></label><label class="field">Category<select name="category">${['Blocked bay','Vehicle assistance','Lost item','Safety concern','Other'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field">Details<textarea name="note" placeholder="Describe the issue or assistance needed" minlength="3" maxlength="500" required></textarea></label>${btn('Log security report','submit-incident','shield','wide')}</form></div></section><section class="panel"><div class="panel-head"><h2>Report status</h2></div><div class="panel-body"><div class="result-grid"><div><span>Open</span><strong>${state.incidents.filter(i=>i.status==='open').length}</strong></div><div><span>Resolved</span><strong>${state.incidents.filter(i=>i.status==='resolved').length}</strong></div><div><span>Closed bays</span><strong>${state.disabled}</strong></div></div><div class="notice">A report does not automatically close a bay. Select a free bay on the map to close it for maintenance; reopen it when safe.</div>${btn('Open floor monitor','nav','map','secondary','data-page="parking"')}</div></section></div><section class="panel"><div class="panel-head"><h2>Incident log</h2><span class="chip gray">Persistent records</span></div>${state.incidents.length?`<div class="table-wrap"><table><thead><tr><th>Report</th><th>Bay</th><th>Details</th><th>Status</th><th>Action</th></tr></thead><tbody>${state.incidents.map(i=>`<tr><td><strong>${esc(i.category)}</strong><br><small class="muted">${date(i.time)} ${time(i.time)}</small></td><td>${esc(i.slot||'General')}</td><td style="white-space:normal;min-width:180px;max-width:360px">${esc(i.note)}</td><td>${chip(i.status)}</td><td>${i.status==='open'?btn('Resolve','resolve','check','secondary small',`data-id="${i.id}"`):'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('No security reports yet.','shield')}</section>`;}
const architectureInfo={visitors:'Visitors enter plates, select destinations, receive routes, confirm parking and find their vehicles. Security records entry, exit and assistance reports.',engine:'A process lock and SQLite transaction coordinate registration, assignment, bay changes, fees and queue promotion. One server worker owns the in-memory registry.',hash:'The active dictionary maps normalized plates to records. Exit removes an active key while retaining the completed visit in SQLite.',astar:'A* searches a weighted aisle graph. Manhattan distance plus minimum ramp cost is admissible. Recommendation minimizes destination walking distance, then driving distance.',queue:'A deque-backed FIFOQueue appends arrivals and removes from the front. Queue promotion occurs atomically with exit or bay reopening.',database:'SQLite stores visits, recorded fees, closed bays, incidents, settings and events. Partial unique indexes enforce one active visit per plate and one vehicle per assigned bay.',analytics:'Recorded visits produce hourly occupancy, entry/exit totals, duration distribution, bay use and revenue. Times use Asia/Bangkok day boundaries.',history:'Explicit stable Merge Sort orders completed visits by the full entry timestamp. Divide/merge trace data drives the visualization.'};
function architecturePage(){const node=(id,label)=>`<button class="architecture-node" data-action="architecture" data-node="${id}">${label}</button>`;return pageHead('One system. Four core ideas.','Select a component to see its role in the complete parking lifecycle.')+`<section class="panel"><div class="architecture">${node('visitors','Visitor / Security UI')}<div class="architecture-arrow">↓</div>${node('engine','Parking engine')}<div class="architecture-arrow">↓</div><div class="architecture-row">${node('hash','Hash table')}${node('astar','A* search')}${node('queue','FIFO queue')}</div><div class="architecture-arrow">↓</div>${node('database','SQLite visit storage')}<div class="architecture-arrow">↓</div><div class="architecture-row">${node('analytics','Analytics & decisions')}${node('history','History / Merge Sort')}</div></div><div class="architecture-detail" id="architecture-detail">${architectureInfo.engine}</div></section><div class="notice" style="margin-top:20px">Entry → plate registry → recommendation → assignment → parking → exit & fee → FIFO promotion → history → analytics. A real backend is implemented; the camera and sample arrivals are simulated.</div>`;}
function settingsPage(){return pageHead('Make it your mall.','Configure your display name, fee policy and 11 destinations.')+`<section class="panel"><div class="panel-head"><h2>Mall settings</h2><span class="chip gray">Saved in SQLite</span></div><div class="panel-body"><form class="form" data-form="settings"><label class="field">Mall display name<input name="mall_name" value="${esc(state.settings.mall_name)}" maxlength="60" required></label><div class="field-row"><label class="field">Free hours<input type="number" name="free_hours" value="${state.settings.free_hours}" min="0" max="24" required></label><label class="field">First billed hour (THB)<input type="number" name="first_hour" value="${state.settings.first_hour}" min="0" max="10000" step="0.01" required></label></div><label class="field">Additional billed hour (THB)<input type="number" name="additional_hour" value="${state.settings.additional_hour}" min="0" max="10000" step="0.01" required></label><p class="muted" style="font-size:11px">Billable hours = max(0, ceil(parking minutes / 60) − free hours). Historical receipts keep the fee calculated at exit; active estimates use the current policy.</p><h3>Destinations · one on each floor</h3><div class="settings-destinations">${state.destinations.map(d=>`<label class="field">Floor ${state.floors[d.floor].name} / Zone ${state.floors[d.floor].zone}<input name="destination_${d.id}" value="${esc(d.name)}" maxlength="60" required></label>`).join('')}</div>${btn('Save settings','submit-settings','check')}<div class="notice" style="margin:0">These are illustrative fees and labels. This project does not use official mall floor plans, cameras or billing services.</div></form></div></section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Simulation studio</h2></div><div class="panel-body"><p class="muted" style="font-size:11px;margin-bottom:17px">Generate arrivals or fill all 1,100 bays to demonstrate queueing. Clearing or resetting demo data preserves manually entered vehicles, settings, bay closures and incidents.</p>${simulationButtons()}</div></section>`;}
function projectPage(){return pageHead('Parking, explained through algorithms.','01416206 Data Structures & Algorithms · Group Understaffed','','About this project')+`<section class="panel"><div class="panel-head"><h2>Parking Lot Management System</h2><span class="chip">Version 2 · Mall edition</span></div><div class="panel-body project-copy"><h3>The problem</h3><p>Mall visitors lose time circling parking floors. Administrators need a reliable view of capacity, and security teams need a fast way to register vehicles, handle departures and assist visitors.</p><h3>Objectives</h3><p>Recommend a connected available bay near a destination, maintain accurate active records, provide a fair waiting queue, and turn completed visits into operating insights. The mall layout contains 1,100 bays across 11 floors with 100 bays on each floor.</p><h3>The four core components</h3><p><strong>Hash table:</strong> normalized license plates key the active registry.<br><strong>A*:</strong> find shortest weighted routes using a safe heuristic.<br><strong>FIFO queue:</strong> serve arrivals in order when capacity is full.<br><strong>Merge Sort:</strong> order visit history by entry timestamp.</p><h3>Stakeholders</h3><p>Visitors use Park My Car and Find My Car. Administrators monitor occupancy, history, analytics and settings. Security uses gate operations, bay controls and incident reports. The role selector demonstrates these workflows and is not an authentication system.</p><h3>Limitations and future improvements</h3><p>Distances and plans are illustrative, inspired by the proposal’s four-row layout and mall workflows. Camera detection is simulated; there is no OCR, real sensor connection, online payment, SMS or access control. Walking routes share the demonstration aisle graph. A production deployment needs verified pedestrian paths, separate driving rules, login and authorization, privacy controls, hardware integration, notification delivery, payment integration and load testing. Use one backend worker for this prototype.</p><h3>Data lifecycle</h3><p>Vehicle entry → data collection → registry → A* recommendation → assigned bay → confirmed parking → vehicle exit → fee receipt → historical storage → Merge Sort → analytics → management decision.</p></div></section>`;}
const slides=[
 ['The problem','Visitors circle the lot. Mall teams lack a clear picture of capacity. This prototype connects the arrival experience with accurate operations and explainable algorithms.','project'],
 ['A connected system','A visitor chooses a destination. The parking engine coordinates the plate registry, A* routing, FIFO waiting and persistent visit history.','architecture'],
 ['The parking map','Explore 1,100 bays across 11 floors. Each floor has 100 bays, four rows, shared aisles and a connection to the next floor. Bay colors also have text labels in their detail panel.','parking'],
 ['A vehicle arrives','Enter ABC-1234, choose a mall destination, and register the visit. A duplicate active plate is rejected. Camera detection can be simulated without hardware.','driver'],
 ['A* recommends a bay','Available bays are ranked by shortest connected walking distance. A* also computes the entrance-to-bay route, showing g(n), h(n), f(n), explored nodes and the final path.','algorithms'],
 ['The hash registry','The normalized plate is a dictionary key. Find, confirm or exit a vehicle through average O(1) key lookup; records remain consistent with bay state.','vehicles'],
 ['Parking fills up','Use Fill all bays, then enter XYZ-5678. It joins the rear of the FIFO queue. Multiple arrivals retain their order until a reachable bay becomes available.','queue'],
 ['A vehicle exits','Record an exit for ABC-1234. The engine stores the fee and exit time, releases its bay, then assigns it to the oldest waiting vehicle in the same transaction.','security'],
 ['Merge Sort orders history','History is divided into smaller lists, then merged by full entry timestamps. The algorithm is implemented explicitly, and the lab animates the same divide/merge trace.','algorithms'],
 ['Visits become insights','Recorded visits power occupancy, arrival and exit charts, revenue, duration distribution and bay turnover. Date filters and heatmaps reveal how demand changes.','analytics'],
 ['Architecture and limits','FastAPI provides the parking API. SQLite persists visits, settings and events. A process lock, database constraints and one server worker protect state transitions.','architecture'],
 ['The result','Visitors find and retrieve cars. Mall admins understand capacity and demand. Security handles arrivals, exits and incidents. Four core algorithms cooperate in one working project.','overview']
];
function presentationPage(){const s=slides[presentationStep];return `<div class="presentation"><div class="eyebrow">Parking Lot Management System · ${presentationStep+1} / ${slides.length}</div><h1>${s[0]}</h1><p>${s[1]}</p><div class="presentation-content">${btn('Open this demonstration','nav','arrow','secondary',`data-page="${s[2]}"`)}${presentationStep===2?`<div class="small-stats"><div class="small-stat"><span>Physical capacity</span><strong>${num(state.capacity)}</strong></div><div class="small-stat"><span>Connected floors</span><strong>${state.floors.length}</strong></div><div class="small-stat"><span>Core algorithms</span><strong>4</strong></div></div>`:''}</div><div class="presentation-footer">${btn('Previous','slide-prev','chevron','secondary') }<span class="muted" style="font-size:10px">${presentationStep+1} of ${slides.length}</span><div class="result-actions">${btn('Fullscreen','fullscreen','expand','secondary')}${btn('Next','slide-next','arrow')}</div></div></div>`;}
function simulationButtons(){return `<div class="simulation-buttons">${[['entry','Simulate entry','enter'],['exit','Simulate exit','exit'],['generate','Generate 10 vehicles','plus'],['generate100','Generate 100 vehicles','plus'],['fill','Fill all 1,100 bays','layers'],['queue','Create queue','queue'],['clear','Clear demo vehicles','trash'],['reset','Reset demo dataset','refresh']].map(([sim,label,ico])=>btn(label,'simulate',ico,'secondary small',`data-sim="${sim}"`)).join('')}</div>`;}
const pages={overview:overviewPage,parking:parkingPage,driver:driverPage,find:findPage,vehicles:vehiclesPage,queue:queuePage,history:historyPage,analytics:analyticsPage,algorithms:algorithmsPage,security:securityPage,incidents:incidentsPage,architecture:architecturePage,settings:settingsPage,project:projectPage,presentation:presentationPage,simulation:simulationPage};

function modal(title,body){
 modalFocus=document.activeElement;
 $('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="panel-head"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="modal-close" aria-label="Close dialog">${icon('close')}</button></div><div class="panel-body">${body}</div></section></div>`;
 requestAnimationFrame(()=>$('.modal input,.modal select,.modal button')?.focus());
}
function closeModal(){ $('#modal-root').innerHTML='';modalFocus?.focus();selectedSlot=null;}
async function slotModal(id){
 const s=state.floors.flatMap(f=>f.slots).find(s=>s.id===id);if(!s)return;
 selectedSlot=s;
 const v=s.plate?await api(`/api/vehicles/${encodeURIComponent(s.plate)}`):null;
 const detail=await api(`/api/slots/${id}?destination=${v?.destination??draft.destination}`);
 const f=state.floors[s.floor];
 modal(`Bay ${s.id}`,`${chip(s.status)}<div class="modal-meta"><div><span>Floor / zone</span><strong>${f.name} / ${f.zone}</strong></div><div><span>Assignments (all time)</span><strong>${s.usage_count}</strong></div><div><span>Current vehicle</span><strong>${esc(s.plate||'None')}</strong></div><div><span>Entry time</span><strong>${v?date(v.entry_time)+' · '+time(v.entry_time):'—'}</strong></div><div><span>Duration</span><strong>${v?duration(v.duration_minutes):'—'}</strong></div><div><span>Distance to ${esc(detail.selected_destination)}</span><strong>${detail.selected_distance} m</strong></div><div><span>Nearest destination</span><strong>${esc(detail.nearest_destination)}</strong></div><div><span>Assignments today</span><strong>${detail.uses_today}</strong></div></div>${s.reason?`<div class="notice warning">Closed: ${esc(s.reason)}</div>`:''}<div class="result-actions">${v?btn('View route','route','map','secondary',`data-plate="${esc(v.plate)}"`):''}${v?.status==='assigned'?btn('Confirm parking','confirm','check','',`data-plate="${esc(v.plate)}"`):''}${role!=='visitor'?(v?btn('Record exit','exit','exit','',`data-plate="${esc(v.plate)}"`):btn(s.status==='disabled'?'Reopen bay':'Close for maintenance','slot-toggle','settings',s.status==='disabled'?'':'danger',`data-slot="${s.id}" data-disabled="${s.status!=='disabled'}"`)):''}</div>`);
}
function receiptModal(r){const v=r.receipt;modal('Departure receipt',`<div class="eyebrow">${esc(state.settings.mall_name)}</div><h3 style="font-size:24px;margin:10px 0">${esc(v.plate)}</h3><p class="muted" style="font-size:11px">Bay ${v.slot} · floor ${state.floors[v.floor].name} · visit complete</p><div class="modal-meta"><div><span>Entry</span><strong>${date(v.entry_time)} ${time(v.entry_time)}</strong></div><div><span>Bay assigned</span><strong>${date(v.parked_time)} ${time(v.parked_time)}</strong></div><div><span>Exit</span><strong>${date(v.exit_time)} ${time(v.exit_time)}</strong></div><div><span>Parking duration</span><strong>${duration(v.duration_minutes)}</strong></div><div><span>Billable hours</span><strong>${v.billable_hours} (${r.rates.free_hours} free)</strong></div><div><span>First / additional hour</span><strong>${money(r.rates.first_hour)} / ${money(r.rates.additional_hour)}</strong></div></div><div class="receipt-total"><span>Total fee</span><strong>${money(v.fee)}</strong></div>${r.promoted.length?`<div class="notice">FIFO served: ${r.promoted.map(v=>esc(v.plate)+' → '+v.slot).join(', ')}. Waiting visitors receive an in-app notification.</div>`:''}<small class="muted">Prototype fee calculation · no payment processed</small>`);}
async function runAstar(){const d=$('#lab-destination')?.value??draft.destination;algorithmResult=await api(`/api/algorithms/astar?destination=${d}`);draft.destination=String(d);if(!algorithmResult.algorithm){toast('No reachable available bays. New arrivals will join the queue.');return false;}result=null;found=null;floor=state.floors.find(f=>f.slots.some(s=>s.id===algorithmResult.algorithm.slot)).id;render();return true;}
async function animateAstar(){
 clearInterval(animationTimer);
 if(page==='algorithms'&&!algorithmResult?.route){if(!await runAstar())return;}
 let route=page==='algorithms'?algorithmResult?.route:page==='find'?found?.route:result?.vehicle?.route||found?.route||algorithmResult?.route;
 if(!route){if(!await runAstar())return;route=algorithmResult.route;}
 const steps=route.driving.steps;animationStep=0;floor=steps[0].node[0];
 const tick=()=>{
  if(animationStep>=steps.length){clearInterval(animationTimer);animationTimer=null;animationStep=-1;const target=route.driving.path.at(-1);floor=target[0];render();toast(`A* complete · ${steps.length} expanded nodes · ${route.driving.distance} m driving route`);return;}
  floor=steps[animationStep].node[0];
  $$('.map-shell').forEach(el=>{const svg=$('svg',el);if(svg)svg.outerHTML=mapSvg();});
  $$('#astar-metrics').forEach(el=>el.innerHTML=astarMetrics());
  $$('.tabs button[data-floor]').forEach(el=>el.classList.toggle('active',Number(el.dataset.floor)===floor));
  animationStep++;
 };
 tick();animationTimer=setInterval(tick,Math.max(45,Math.floor(6500/steps.length)));
}
function animateMerge(){
 if(!mergeData?.trace.length){toast('Record a completed visit first.');return;}
 clearInterval(animationTimer);let index=0;
 const trace=$('#merge-trace');
 animationTimer=setInterval(()=>{if(!trace?.isConnected){clearInterval(animationTimer);animationTimer=null;return;}const step=mergeData.trace[index++];if(!step){clearInterval(animationTimer);animationTimer=null;trace.innerHTML=`<div class="trace-label">Output · sorted full entry timestamps</div><div class="trace">${mergeData.output.map(v=>`<span>${date(v)} ${time(v)}</span>`).join('')}</div>`;toast('Merge Sort complete · O(n log n)');return;}trace.innerHTML=`<div class="trace-label">Step ${index} / ${mergeData.trace.length} · ${step.operation}</div><div class="trace">${step.values.map(v=>`<span>${date(v)} ${time(v)}</span>`).join('')}</div><div class="progress"><i style="width:${index/mergeData.trace.length*100}%"></i></div>`;},500);
}
async function mutate(fn){if(busy)return;busy=true;const buttons=$$('button[data-action]');buttons.forEach(b=>b.disabled=true);try{await fn();}catch(e){if(page==='find'){found=null;render();}toast(e.message,true);}finally{busy=false;$$('button[data-action]').forEach(b=>b.disabled=false);}}
async function handleAction(el){
 const action=el.dataset.action;
 if(action.startsWith('submit-'))return;
 if(await handleLabToolsAction(el))return;
 if(action==='nav'){closeModal();return navigate(el.dataset.page);}
 if(action==='menu'){return $('.sidebar').classList.add('open')||$('.mobile-shade').classList.add('open');}
 if(action==='menu-close'){$('.sidebar').classList.remove('open');$('.mobile-shade').classList.remove('open');return;}
 if(action==='modal-close'){closeModal();return;}
 if(action==='floor'){floor=Number(el.dataset.floor);render();return;}
 if(action==='map-mode'){mapMode=el.dataset.mode;render();return;}
 if(action==='slot'){return slotModal(el.dataset.slot);}
 if(action==='architecture'){$('#architecture-detail').textContent=architectureInfo[el.dataset.node];return;}
 if(action==='notifications'){modal('Recent parking activity',recentActivity(12));return;}
 if(action==='simulation'){modal('Simulation studio',`<p class="muted" style="font-size:11px;margin-bottom:20px">Demonstrate arrivals, full capacity, FIFO promotion and history without cameras. Demo records are labeled and can be cleared while keeping manual visits.</p>${simulationButtons()}<div class="divider"></div>${btn('Open simulation control mode','nav','play','','data-page="simulation"')}`);return;}
 if(action==='arrival'){modal('Register a mall arrival',entryForm());return;}
 if(action==='camera'){draft.plate='SIM'+Math.floor(100000+Math.random()*900000);$$('[data-draft="plate"]').forEach(e=>e.value=draft.plate);toast('Simulated plate detection. Choose a destination and register this arrival.');return;}
 if(action==='scroll-park'){$('#park-form').scrollIntoView({behavior:'smooth',block:'start'});$('#park-form input').focus({preventScroll:true});return;}
 if(action==='slide-prev'||action==='slide-next'){presentationStep=Math.max(0,Math.min(slides.length-1,presentationStep+(action==='slide-next'?1:-1)));render();return;}
 if(action==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.presentation').requestFullscreen();}catch(e){toast('Fullscreen is unavailable in this browser.',true);}return;}
 if(action==='animate-merge'){animateMerge();return;}
 if(action==='animate-astar'){return animateAstar();}
 if(action==='custom-range'){modal('Choose analytics dates',`<form class="form" data-form="custom-range"><label class="field">Start date<input type="date" name="start" required value="${customStart}"></label><label class="field">End date<input type="date" name="end" required value="${customEnd}"></label>${btn('Apply range','submit-range','chart')}</form>`);return;}
 await mutate(async()=>{
  if(action==='compare'){const c=await api(`/api/algorithms/compare?destination=${draft.destination}`);const out=$('#compare-output');out.style.display='block';out.innerHTML=`<div class="notice">Same entrance and bay ${c.slot}: A* explored ${c.astar.expanded} nodes; Dijkstra explored ${c.dijkstra.expanded}. Both found a ${c.astar.distance} m shortest route. Median of 7 timed searches after warm-up: A* ${runtime(c.astar.median_ms)}; Dijkstra ${runtime(c.dijkstra.median_ms)}. A* uses the heuristic; Dijkstra sets h(n)=0. A* remains the primary parking algorithm.</div>`;return;}
  if(action==='run-astar'){await runAstar();return;}
  if(action==='range'){days=Number(el.dataset.days);customStart='';customEnd='';analytics=await api(analyticsUrl());mapMode='heat';render();return;}
  if(action==='route'){const v=await api(`/api/vehicles/${encodeURIComponent(el.dataset.plate)}`);found=v;result=null;algorithmResult=null;if(v.floor!==null)floor=v.floor;closeModal();if(v.status==='waiting'){page='find';draft.findPlate=v.plate;}else page=role==='visitor'?'find':'parking';render();location.hash=page;return;}
  if(action==='confirm'){const v=await api('/api/confirm',{plate:el.dataset.plate});if(result?.vehicle?.plate===v.plate)result.vehicle=v;if(found?.plate===v.plate)found=v;closeModal();await refresh();render();toast(`${v.plate} confirmed in ${v.slot}`);return;}
  if(action==='cancel'){await api('/api/queue/cancel',{plate:el.dataset.plate});if(result?.vehicle?.plate===el.dataset.plate)result=null;if(found?.plate===el.dataset.plate)found=null;closeModal();await refresh();render();toast('Queue entry cancelled. Remaining positions updated.');return;}
  if(action==='exit'){const r=await api('/api/exit',{plate:el.dataset.plate});if(result?.vehicle?.plate===el.dataset.plate)result=null;if(found?.plate===el.dataset.plate)found=null;await refresh();if(page==='history')historyData=(await api('/api/history')).records;render();receiptModal(r);return;}
  if(action==='slot-toggle'){await api(`/api/slots/${el.dataset.slot}`,{disabled:el.dataset.disabled==='true',reason:'Security / maintenance'},'PATCH');closeModal();await refresh();render();toast('Bay state updated.');return;}
  if(action==='resolve'){await api(`/api/incidents/${el.dataset.id}/resolve`,{});await refresh();render();toast('Incident resolved.');return;}
  if(action==='simulate'){
   const sim=el.dataset.sim;
   const chosenDestination=$('#simulation-destination')?.value;
   const simulationDestination=chosenDestination==='random'?null:Number(chosenDestination??draft.destination);
   const data=await api('/api/simulate',{action:sim==='generate100'||sim==='custom'?'generate':sim,count:sim==='custom'?trafficConfig.batch:sim==='generate100'?100:10,destination:simulationDestination});
   if(data.vehicle){result={vehicle:data.vehicle,algorithm:data.algorithm};found=null;algorithmResult=null;if(data.vehicle.floor!==null)floor=data.vehicle.floor;}
   if(['clear','reset','exit'].includes(sim)){result=null;found=null;algorithmResult=null;}
   closeModal();await refresh();if(page==='history')historyData=(await api('/api/history')).records;if(page==='algorithms')mergeData=await api('/api/algorithms/merge');if(page==='simulation'&&!scenarioCatalog.length)scenarioCatalog=(await api('/api/simulation/scenarios')).scenarios;render();if(data.receipt)receiptModal(data);else toast(data.message||'Simulation complete.');return;
  }
 });
}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el&&!el.disabled)handleAction(el).catch(e=>toast(e.message,true));if(event.target.classList.contains('modal-overlay'))closeModal();});
document.addEventListener('keydown',event=>{
 if(event.key==='Escape'){closeModal();$('.sidebar')?.classList.remove('open');$('.mobile-shade')?.classList.remove('open');}
 if(event.key==='Enter'||event.key===' '){const el=event.target.closest('.map-slot');if(el){event.preventDefault();handleAction(el).catch(e=>toast(e.message,true));}}
 if(event.key==='Tab'&&$('.modal')){const nodes=$$('button:not(:disabled),input,select,textarea,a[href]', $('.modal'));const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
});
document.addEventListener('input',event=>{
 const el=event.target;if(el.dataset.draft)draft[el.dataset.draft]=el.value;
 if(el.id==='vehicle-search'){searchQuery=el.value;const pos=el.selectionStart;render();const input=$('#vehicle-search');input.focus();input.setSelectionRange(pos,pos);}
});
document.addEventListener('change',async event=>{
 const el=event.target;
 if(el.dataset.draft)draft[el.dataset.draft]=el.value;
 if(el.id==='role'){stopTraffic('View changed; traffic paused');role=el.value;localStorage.setItem('parkside-role',role);closeModal();await navigate(role==='visitor'?'driver':role==='security'?'security':'overview');}
 if(el.id==='history-order'){sortOrder=el.value;await navigate('history');}
 if(el.id==='lab-destination')draft.destination=el.value;
});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!form.dataset.form)return;event.preventDefault();const data=Object.fromEntries(new FormData(form));
 if(form.dataset.form==='benchmark'){await runBenchmark(data);return;}
 await mutate(async()=>{
  switch(form.dataset.form){
   case 'entry':result=await api('/api/entry',{plate:data.plate,destination:Number(data.destination)});found=null;algorithmResult=null;draft.plate=data.plate;draft.destination=data.destination;if(result.vehicle.floor!==null)floor=result.vehicle.floor;closeModal();await refresh();render();toast(result.vehicle.status==='waiting'?`Queue position #${result.vehicle.queue_position}`:`Bay ${result.vehicle.slot} assigned. Follow the route and confirm parking.`);break;
   case 'find':found=await api(`/api/vehicles/${encodeURIComponent(data.plate)}`);result=null;algorithmResult=null;if(found.floor!==null)floor=found.floor;render();toast(found.slot?`Your car is in ${found.slot} on floor ${state.floors[found.floor].name}`:`Queue position #${found.queue_position}`);break;
   case 'exit':{const r=await api('/api/exit',{plate:data.plate});if(result?.vehicle?.plate===r.receipt.plate)result=null;if(found?.plate===r.receipt.plate)found=null;await refresh();render();receiptModal(r);break;}
   case 'history':searchQuery=data.query;await navigate('history');break;
   case 'incident':await api('/api/incidents',{slot:data.slot.trim().toUpperCase()||null,category:data.category,note:data.note});await refresh();render();toast('Security report saved.');break;
   case 'settings':await api('/api/settings',{mall_name:data.mall_name,free_hours:Number(data.free_hours),first_hour:Number(data.first_hour),additional_hour:Number(data.additional_hour),destinations:state.destinations.map(d=>data[`destination_${d.id}`])},'PUT');await refresh();render();toast('Mall settings saved.');break;
   case 'custom-range':{const url=`/api/analytics?start=${encodeURIComponent(data.start)}&end=${encodeURIComponent(data.end)}`;analytics=await api(url);customStart=data.start;customEnd=data.end;closeModal();mapMode='heat';render();break;}
  }
 });
});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(p!==page&&pages[p])navigate(p);});
async function init(){
 try{await refresh();await navigate(pages[page]?page:'overview');setInterval(async()=>{
  if(busy)return;
  try{const previousEvent=lastEventId;await refresh(page!=='history');const focus=document.activeElement;const label=$('.sync');if(label)label.innerHTML=`<span class="dot"></span>Live · synced ${time(state.updated_at)}`;if((previousEvent!==lastEventId||Date.now()-lastRenderAt>60000)&&!$('#modal-root').children.length&&!animationTimer&&!['INPUT','SELECT','TEXTAREA','BUTTON'].includes(focus.tagName)&&!focus.closest('.map-slot'))render();}catch(e){const label=$('.sync');if(label)label.textContent='Connection paused · retrying';}
 },5000);}catch(e){$('#app').innerHTML=`<div class="loading"><div><h2>Unable to load the parking service.</h2><p>${esc(e.message)}</p><button class="btn" onclick="location.reload()">Try again</button></div></div>`;}
}
init();
